(() => {
  const root = document.getElementById('launchpad-prototype');
  const main = root.querySelector('#lp-main');
  const feedback = root.querySelector('#lp-feedback');
  const opportunities = [
    {id:'harbor',type:'internship',org:'Harbor Systems',title:'Software Engineering Intern',track:'SWE',place:'New York, NY',cycle:'Summer 2027',fit:'Strong project match',eligibility:'Review requirements',skills:'Java · Python · REST APIs',reason:'Your Spring Boot and Python projects support backend development.',deadline:'Not stated',amount:'—',effort:'Routine fields',prompt:''},
    {id:'cedar',type:'internship',org:'Cedar Cloud',title:'Cloud Security Intern',track:'Security',place:'Seattle, WA',cycle:'Summer 2027',fit:'Partial project match',eligibility:'Review requirements',skills:'Linux · Docker · IAM',reason:'Linux and Docker have résumé evidence. Hands-on IAM experience is not recorded.',deadline:'Not stated',amount:'—',effort:'Screening questions',prompt:''},
    {id:'meridian',type:'internship',org:'Meridian Research',title:'Undergraduate AI Research Intern',track:'Research',place:'Boston, MA',cycle:'Summer 2027',fit:'Strong project match',eligibility:'Review requirements',skills:'Python · Semantic search · Knowledge graphs',reason:'Campus inventory API provides relevant project evidence. Research experience requirements still need checking.',deadline:'Not stated',amount:'—',effort:'Research statement',prompt:'Describe a research project you would like to develop.'},
    {id:'future',type:'scholarship',org:'Future Builders Foundation',title:'Computing Leadership Scholarship',track:'Leadership',place:'No location exclusion in this demo',cycle:'2027–28',fit:'Leadership evidence',eligibility:'Citizenship rules unknown',skills:'CS enrollment · Leadership · Community impact',reason:'Demo Coding Club and Demo Campus Hackathon support leadership claims. Sponsor eligibility must be verified.',deadline:'Oct 20, 2026 · 5 PM EDT (sample)',amount:'$5,000 USD',effort:'Essay + recommendation',prompt:'How have you helped build a technology community?'},
    {id:'trust',type:'scholarship',org:'Digital Trust Scholars Fund',title:'Cybersecurity Student Award',track:'Security',place:'Institution rules need checking',cycle:'2027–28',fit:'Security evidence',eligibility:'Enrollment rules unknown',skills:'Cybersecurity studies · GPA · Career interests',reason:'Your cybersecurity concentration, GPA, and threat intelligence project are relevant evidence.',deadline:'Nov 15, 2026 (sample; time unknown)',amount:'$2,500 USD',effort:'Short statement',prompt:'Describe your interest in cybersecurity.'},
    {id:'access',type:'scholarship',org:'Open Horizons Fund',title:'Undergraduate Technology Grant',track:'CS',place:'Institution rules need checking',cycle:'2027–28',fit:'CS enrollment evidence',eligibility:'Financial criteria unknown',skills:'Undergraduate enrollment · Financial criteria',reason:'CS enrollment is supported. No financial-need facts have been provided.',deadline:'Not stated',amount:'Up to $3,000 USD',effort:'Financial declaration',prompt:''}
  ];
  const defaults = {
    page:'home',scope:'all',selected:'future',paused:true,appId:'scholar-sample',query:'',track:'',
    drafts:{},approvedEssays:{},saved:[],
    importDraft:{type:'internship',org:'',title:'',cycle:'',date:'',stage:'Applied',notes:''},
    apps:[
      {id:'manual-sample',type:'internship',org:'Northstar Computing',title:'Software Engineering Intern',cycle:'Summer 2027',stage:'Interview',origin:'Manual sample',evidence:'User reported (sample)',date:'2026-10-12',history:['Application reported · Oct 12, 2026 (sample)','Interview invitation recorded (sample)']},
      {id:'uncertain-sample',type:'internship',org:'Juniper Labs',title:'Security Engineering Intern',cycle:'Summer 2027',stage:'Ready',origin:'Agent sample',evidence:'Uncertain',date:'',history:['Sample attempt interrupted after Submit','Outcome uncertain · Retry blocked']},
      {id:'scholar-sample',type:'scholarship',org:'Community Futures Foundation',title:'Student Leadership Award',cycle:'2026–27',stage:'Under review',origin:'Manual sample',evidence:'User reported (sample)',date:'2026-10-10',history:['Scholarship application manually logged (sample)','Sponsor review pending (sample)']},
      {id:'renewal-sample',type:'scholarship',org:'Tomorrow Scholars Fund',title:'Technology Scholars Award',cycle:'2026–27',stage:'Awarded',origin:'Manual sample',evidence:'Sample award notice',date:'2026-09-15',history:['Illustrative award notice recorded','Acceptance and disbursement not recorded'],award:'$1,000 USD offered · Acceptance unknown · Received: not recorded'}
    ]
  };
  let state = structuredClone(defaults), importPreview = false, importMode = 'details';
  const stored = window.openai?.widgetState?.privateContent;
  if (stored?.version===2 && Array.isArray(stored.state?.apps)) state={...structuredClone(defaults),...stored.state};
  const esc = value => String(value??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
  const titleType = t => t==='scholarship'?'Scholarship':'Internship';
  const inScope = item => state.scope==='all'||item.type===state.scope;
  const stages = type => type==='scholarship'?['Submitted','Under review','Shortlisted','Awarded','Not selected','Withdrawn']:['Applied','Assessment','Interview','Offer','Rejected','Withdrawn'];
  const btn=(label,action,extra='')=>`<button type="button" data-action="${action}" ${extra}>${label}</button>`;
  const tag=(label,tone='neutral')=>`<span class="status ${tone}">${esc(label)}</span>`;
  const heading=(title,sub)=>`<h1>${esc(title)}</h1><p class="muted">${esc(sub)}</p>`;
  const role=()=>opportunities.find(r=>r.id===state.selected)||opportunities[0];
  const app=()=>state.apps.find(a=>a.id===state.appId);
  const norm=x=>String(x).trim().toLowerCase().replace(/[–—]/g,'-');
  const duplicate=d=>state.apps.find(a=>a.type===d.type&&norm(a.org)===norm(d.org)&&norm(a.title)===norm(d.title)&&norm(a.cycle)===norm(d.cycle));
  function persist(){
    const data={version:2,state};
    if(JSON.stringify(data).length>15000){say('Session changes are visible, but the preview storage limit was reached.');return;}
    window.openai?.setWidgetState?.({modelContent:{prototype:'Lelouvre',screen:state.page,scope:state.scope,submissionsPaused:state.paused},privateContent:data})?.catch(()=>{});
  }
  function say(text){feedback.textContent=text;}
  function captureImport(){const form=root.querySelector('#lp-import-form');if(form)state.importDraft=Object.fromEntries(new FormData(form));}
  function go(page){captureImport();state.page=page;importPreview=false;say('');render();persist();}
  function scopeControl(){return `<div class="scope-control" role="group" aria-label="Opportunity scope">${[['all','All'],['internship','Internships'],['scholarship','Scholarships']].map(([v,l])=>`<button type="button" data-action="scope" data-scope="${v}" aria-pressed="${state.scope===v}">${l}</button>`).join('')}</div>`;}
  function task(title,text,action,label,tone='review',extra=''){return `<article class="task"><div>${tag(tone==='urgent'?'Urgent':tone==='info'?'Upcoming':'Needs review',tone)}<h3>${esc(title)}</h3><p class="muted">${esc(text)}</p></div>${btn(label,action,extra)}</article>`;}
  function render(){
    root.querySelectorAll('[data-page]').forEach(b=>{if(b.dataset.page===state.page)b.setAttribute('aria-current','page');else b.removeAttribute('aria-current');});
    let scope=root.querySelector('#lelouvre-scope');
    if(!scope){scope=document.createElement('div');scope.id='lelouvre-scope';root.querySelector('aside').append(scope);}
    scope.innerHTML=scopeControl();
    if(state.page==='home')renderHome();
    if(state.page==='opportunities')renderOpportunities();
    if(state.page==='role')renderRole();
    if(state.page==='review')renderReview();
    if(state.page==='applications')renderApplications();
    if(state.page==='detail')renderDetail();
    if(state.page==='import')renderImport();
    if(state.page==='settings')renderSettings();
  }
  function renderHome(){
    const scholar=state.scope!=='internship',intern=state.scope!=='scholarship';
    main.innerHTML=`<div class="row between"><div class="eyebrow">DEMO WORKSPACE · INTERNSHIPS & SCHOLARSHIPS</div>${tag(state.paused?'Submissions paused':'Demo queue enabled')}</div>`+heading('Your next chapter.','Decisions, deadlines, and applications in one place.')+`<div class="scope-strip"><span>Internships: Summer 2027 · Outside SC</span><span>Scholarships: relevant award cycles</span><span>Live scouting not connected</span></div><div class="home-grid"><section><h2>Needs you</h2>${scholar?`<div class="focus-card">${tag('Urgent · Sample deadline','urgent')}<h3>Computing Leadership Scholarship</h3><p>Essay and recommendation needed · Oct 20, 2026, 5 PM EDT (sample).</p><p class="muted">Eligibility is not confirmed. Review the requirements before preparing.</p>${btn('Review scholarship','reviewrole','class="primary" data-id="future"')}</div>`:''}${intern?`<div class="quiet-section">${task('Meridian Research','Review your research statement and unanswered requirements.','reviewrole','Review packet','review','data-id="meridian"')}</div>`:''}${scholar?`<div class="quiet-section">${task('Technology Scholars Award','Acceptance and payment are unrecorded. Verify renewal conditions in the award notice.','openapp','View award','review','data-id="renewal-sample"')}</div>`:''}<div class="quiet-section"><h3>Already submitted something?</h3><p class="muted">Log an internship or scholarship to keep your history together.</p>${btn('+ Log an application','import')}</div></section><section><h2>Keep in view</h2>${intern?`<div class="panel">${tag('Check outcome','review')}<h3>Juniper Labs</h3><p class="muted">${state.apps.find(a=>a.id==='uncertain-sample')?.evidence==='Uncertain'?'Submission confirmation missing. Retry stays blocked.':'Recorded as user reported; no receipt attached.'}</p>${btn('Open application','openapp','data-id="uncertain-sample"')}</div><div class="quiet-section">${task('Northstar Computing','Interview stage · Prepare project examples.','openapp','Open interview','info','data-id="manual-sample"')}</div>`:''}${scholar?`<div class="panel">${tag('Under review','info')}<h3>Student Leadership Award</h3><p class="muted">Manually logged scholarship · Awaiting a decision in this sample.</p>${btn('View application','openapp','data-id="scholar-sample"')}</div>`:''}<div class="quiet-section"><div class="eyebrow">AGENT STATUS</div><p>Preview only · Email and background services are not connected.</p>${btn(state.paused?'Enable demo queue':'Pause submissions','pause')}</div></section></div><div class="legend">${tag('Urgent','urgent')}${tag('Needs review','review')}${tag('In progress','info')}${tag('Confirmed','success')}${tag('Inactive')}</div>`;
    if(scholar&&state.recommendationTask)main.querySelector('.home-grid>section').insertAdjacentHTML('beforeend',`<div class="quiet-section">${task('Recommendation requirement','Choose a recommender and confirm the process. Nobody has been contacted.','reviewrole','Open requirement','review','data-id="future"')}</div>`);
    if(scholar&&state.apps.some(a=>a.renewalTask))main.querySelector('.home-grid>section').insertAdjacentHTML('beforeend',`<div class="quiet-section">${task('Verify renewal terms','Reminder saved with no deadline until the award terms are checked.','openapp','View award','review','data-id="renewal-sample"')}</div>`);
  }
  function cards(){
    const list=opportunities.filter(r=>inScope(r)&&(!state.track||r.track===state.track)&&`${r.org} ${r.title} ${r.skills}`.toLowerCase().includes(state.query.toLowerCase()));
    return list.map(r=>`<article class="panel"><div class="row between"><span class="small muted">${esc(r.org)} · ${titleType(r.type)}</span>${tag(r.type==='scholarship'?r.amount:r.track)}</div><h3>${esc(r.title)}</h3><p class="muted">${esc(r.cycle)} · ${esc(r.effort)}</p><p>${esc(r.fit)} · ${tag(r.eligibility,'review')}</p><p class="small muted">${esc(r.deadline)}${r.type==='internship'?' · '+esc(r.place):''}</p><div class="row">${btn('View opportunity','viewrole',`data-id="${r.id}"`)}${btn(state.saved.includes(r.id)?'Saved':'Save','save',`data-id="${r.id}" aria-pressed="${state.saved.includes(r.id)}"`)}</div></article>`).join('')||'<p class="empty">No sample opportunities match. Try another scope or filter.</p>';
  }
  function renderOpportunities(){
    const tracks=[...new Set(opportunities.filter(inScope).map(r=>r.track))];
    if(!tracks.includes(state.track))state.track='';
    main.innerHTML=heading('Explore opportunities','Fictional samples show how matching and requirements will appear.')+`<div class="row toolbar"><label>Search<input id="lp-search" value="${esc(state.query)}" placeholder="Company, sponsor, role, or skill"></label><label>Focus<select id="lp-track"><option value="">All areas</option>${tracks.map(t=>`<option ${state.track===t?'selected':''}>${esc(t)}</option>`).join('')}</select></label></div><div id="lp-results" class="opportunity-grid">${cards()}</div>`;
  }
  function renderRole(){const r=role();
    main.innerHTML=heading(r.title,`${r.org} · ${r.cycle}`)+`<div class="row">${tag(titleType(r.type))}${tag(r.eligibility,'review')}${tag(r.fit,'info')}</div><div class="cols"><section class="panel"><h3>Why it may fit</h3><p>${esc(r.reason)}</p><h3>Requirements to check</h3><p>${esc(r.skills)}</p><p class="muted">${r.type==='scholarship'?'Citizenship, institution, financial criteria, and award terms need official verification. CPT eligibility does not establish scholarship eligibility.':'Exact role requirements and eligibility need official verification.'}</p></section><section class="panel"><h3>${r.type==='scholarship'?'Award details':'Internship details'}</h3><p>${r.type==='scholarship'?'Amount: '+esc(r.amount):esc(r.place)}</p><p>Deadline: ${esc(r.deadline)}</p><p>Materials: ${esc(r.effort)}</p><p>${r.type==='scholarship'?'Renewable: unknown':'Season: Summer 2027'}</p><p class="small muted">Fictional source · No verified application destination.</p></section></div><div class="row actions">${btn('Prepare / review packet','review','class="primary"')}${btn('I already submitted','prefill')}${btn('Back to opportunities','opportunities')}</div>`;
  }
  function renderReview(){const r=role(),isScholar=r.type==='scholarship';
    const defaultText=isScholar?'I founded Demo Coding Club at Demo State University and organized Demo Campus Hackathon to help students build practical technology skills and connect with peers.': 'I am developing Campus inventory API, a research discovery platform using Python, semantic search, and knowledge graphs.';
    main.innerHTML=heading('Review application',`${r.org} · ${titleType(r.type)} · ${r.cycle}`)+`<div class="callout">${tag('Submission blocked','review')} Official destination and eligibility need verification. This is a sample packet.</div><div class="cols"><section class="panel"><h3>Exact answers & materials</h3><p>Jordan Demo · Demo State University<br>Computer Science · May 2028 · GPA 3.65</p>${isScholar?'<p>Citizenship / financial need: not supplied. Never inferred from student work authorization.</p>':'<p>Standard US work-authorization screening: Yes, review required — fictional example.<br>Now/future sponsorship: review required (fictional).<br>Employer-specific CPT approval: not provided — fictional example.</p>'}${r.prompt?`<label>${esc(r.prompt)}<textarea id="lp-writing" maxlength="2000">${esc(state.drafts[r.id]??defaultText)}</textarea></label><p class="small muted">Draft uses résumé project/leadership evidence. Each new prompt needs review.</p><div class="row">${btn('Save draft','savewriting')}${btn(state.approvedEssays[r.id]?'Sample text approved':'Approve sample text','approvewriting',`aria-pressed="${Boolean(state.approvedEssays[r.id])}"`)}</div>`:'<p>No essay in this sample. Unknown screening or financial answers still block submission.</p>'}${r.id==='future'?'<div class="quiet-section"><h3>Recommendation</h3><p>Not requested. A task can track this requirement; no one is contacted automatically.</p>'+btn('Add recommendation task','recommend')+'</div>':''}</section><section class="panel"><h3>Packet checklist</h3><p>${tag('Known','success')} Education facts from your résumé</p><p>${tag('Needs review','review')} Eligibility and exact terms</p><p>${tag('Not connected')} Official destination</p><p>${tag('Not uploaded')} Approved document version</p><p>${tag('Preview only')} Submission adapter</p>${isScholar?'<p>Financial documents, fees, award obligations, and acceptance require your review.</p>':''}<p>Approving sample text does not approve the whole application or send it.</p></section></div><div class="row actions">${btn('Approve complete packet','approvepacket','disabled')}${btn('Queue submission','queue','disabled')}${btn('Back to opportunity','backrole')}</div>`;
  }
  function renderApplications(){
    const list=state.apps.filter(inScope);
    main.innerHTML=heading('My applications','One history, with separate stages for internships and scholarships.')+`<div class="row between"><p>${list.length} sample records · ${list.filter(a=>a.evidence==='Uncertain').length} uncertain</p>${btn('+ Log an application','import','class="primary"')}</div><div class="application-table"><div class="application-row table-head"><span>Company / sponsor</span><span>Stage & evidence</span><span>Submitted</span><span>Next action</span></div>${list.map(a=>`<article class="application-row"><div><h3>${esc(a.org)}</h3><div>${esc(a.title)}</div><div class="small muted">${titleType(a.type)} · ${esc(a.cycle)} · ${esc(a.origin)}</div></div><div>${tag(a.stage,['Applied','Submitted'].includes(a.stage)?'success':a.stage==='Ready'?'review':'info')}<div class="small muted">${esc(a.evidence)}</div></div><div><span class="mobile-label">Submitted: </span>${a.date?esc(a.date):'Unconfirmed'}</div><div>${btn(a.evidence==='Uncertain'?'Check outcome':a.stage==='Awarded'?'View award':'Open record','openapp',`data-id="${esc(a.id)}"`)}</div></article>`).join('')||'<p class="empty">No records in this scope. Log an application to begin.</p>'}</div><p class="small muted">These records are illustrative. Submitted does not mean selected; awarded does not mean accepted or paid.</p>`;
  }
  function renderDetail(){const a=app();if(!a){state.page='applications';render();return;}
    main.innerHTML=heading(a.org,`${a.title} · ${a.cycle}`)+`<div class="row">${tag(titleType(a.type))}${tag(a.stage,'info')}<span>${esc(a.evidence)}</span></div>${a.evidence==='Uncertain'?`<div class="callout">${tag('Outcome uncertain','review')}<p>Retry blocked. Your report can update tracking without creating a receipt.</p>${btn('Record that I submitted','reportsubmitted')}</div>`:''}${a.award?`<div class="panel"><h3>Award record</h3><p>${esc(a.award)}</p><p class="muted">Acceptance, payment, and renewal conditions are separate records. No funds have been received in this demo.</p>${btn('Add renewal reminder','renewal')}</div>`:''}<div class="cols"><section><h2>Timeline</h2><div class="timeline">${a.history.map(h=>`<p>${esc(h)}</p>`).join('')}</div><p class="small muted">Documents and confirmation: not attached in this preview.</p></section><section class="panel"><h3>Update progress</h3><label>Application stage<select id="lp-stage">${stages(a.type).map(s=>`<option ${a.stage===s?'selected':''}>${esc(s)}</option>`).join('')}</select></label>${btn('Save status update','updatestage')}<label>Note<textarea id="lp-note" maxlength="1200" placeholder="Add a response or preparation note"></textarea></label>${btn('Add note','addnote')}<p class="small muted">Marking a stage records your report; it does not contact the organization or accept an award.</p></section></div><div class="actions">${btn('Back to applications','applications')}</div>`;
  }
  function renderImport(){const d=state.importDraft;
    main.innerHTML=heading('Log an application','Record an internship or scholarship you already submitted.')+`<div class="row">${btn('Enter details','modedetails')}${btn('Paste text','modetext')}${btn('Attach confirmation','modefile')}</div>${importMode==='text'?'<label>Confirmation text<textarea id="lp-paste" placeholder="Reference only; extraction is not connected"></textarea></label>':importMode==='file'?'<label>Confirmation file<input type="file" id="lp-file" accept=".pdf,.png,.jpg,.jpeg,.eml"></label><p id="lp-file-status" class="small muted">File selection only. Nothing is uploaded or parsed.</p>':''}<form id="lp-import-form"><label>Application type<select name="type" id="lp-import-type"><option value="internship" ${d.type==='internship'?'selected':''}>Internship</option><option value="scholarship" ${d.type==='scholarship'?'selected':''}>Scholarship</option></select></label><div class="cols"><label>${d.type==='scholarship'?'Sponsor':'Company'} *<input name="org" required maxlength="100" value="${esc(d.org)}"></label><label>${d.type==='scholarship'?'Scholarship name':'Role'} *<input name="title" required maxlength="140" value="${esc(d.title)}"></label><label>${d.type==='scholarship'?'Award cycle / academic year':'Internship cycle'} *<input name="cycle" required maxlength="40" placeholder="${d.type==='scholarship'?'2027–28':'Summer 2027'}" value="${esc(d.cycle)}"></label><label>Submitted date (optional)<input name="date" type="date" value="${esc(d.date)}"></label></div><label>Current stage<select name="stage">${stages(d.type).map(s=>`<option ${d.stage===s?'selected':''}>${esc(s)}</option>`).join('')}</select></label><label>Notes (optional)<textarea name="notes" maxlength="1200">${esc(d.notes)}</textarea></label><button class="primary" type="submit">Review and save</button></form><div id="lp-import-preview"></div><p class="small muted">A cycle is required in this preview to distinguish repeat annual applications. Production will allow unresolved cycle information with a review flag.</p>`;
  }
  function renderSettings(){
    main.innerHTML=heading('Profile & controls','Shared facts, separate eligibility rules.')+`<div class="cols"><section class="panel"><h3>Approved internship screening answers</h3><p>Standard work-authorization question: review required (fictional).</p><p>Now/future sponsorship: review required (fictional).</p><p>Employer-specific CPT: not provided — fictional example.</p><h3>Scholarship facts still needed</h3><p>Citizenship/residency criteria, financial-need information, and program-specific eligibility must not be inferred.</p></section><section class="panel"><h3>Automation</h3><p>${state.paused?'Paused':'Demo queue enabled'} · No live adapters connected</p>${btn(state.paused?'Enable demo queue':'Pause submissions','pause')}<h3 style="margin-top:18px">Email</h3><p>Digest plus urgent alerts · Not connected</p><h3>Coverage</h3><p>Planned: employer/sponsor pages, LinkedIn, web, Reddit, X, research and scholarship lists.</p><p class="muted">No source is actively monitored in this preview.</p></section></div><h2>Preview controls</h2>${btn('Reset sample data','reset')}`;
  }
  root.addEventListener('click',e=>{
    const b=e.target.closest('button');if(!b||b.disabled)return;
    if(b.dataset.page){if(b.dataset.page==='import'){captureImport();if(!state.importDraft.org){state.importDraft.type=state.scope==='scholarship'?'scholarship':'internship';state.importDraft.stage=stages(state.importDraft.type)[0];}}go(b.dataset.page);return;}
    const a=b.dataset.action;
    if(a==='scope'){captureImport();state.scope=b.dataset.scope;state.track='';if(['role','review','detail'].includes(state.page))state.page='opportunities';render();persist();return;}
    if(['home','opportunities','applications','settings','import'].includes(a)){if(a==='import'&&!state.importDraft.org){state.importDraft.type=state.scope==='scholarship'?'scholarship':'internship';state.importDraft.stage=stages(state.importDraft.type)[0];}go(a);return;}
    if(a==='pause'){state.paused=!state.paused;render();say(state.paused?'Submission queue paused.':'Demo queue enabled. No real submissions are possible.');}
    if(a==='viewrole'||a==='reviewrole'){state.selected=b.dataset.id;go(a==='viewrole'?'role':'review');}
    if(a==='review')go('review');if(a==='backrole')go('role');
    if(a==='save'){const id=b.dataset.id;state.saved=state.saved.includes(id)?state.saved.filter(x=>x!==id):[...state.saved,id];root.querySelector('#lp-results').innerHTML=cards();say('Saved opportunity selection updated.');}
    if(a==='savewriting'||a==='approvewriting'){const r=role();state.drafts[r.id]=root.querySelector('#lp-writing').value;state.approvedEssays[r.id]=a==='approvewriting';renderReview();say(a==='approvewriting'?'Sample text approved. The complete packet remains blocked.':'Draft saved; prior text approval cleared.');}
    if(a==='recommend'){state.recommendationTask=true;say('Recommendation task added in this preview. Nobody was contacted.');}
    if(a==='prefill'){const r=role();state.importDraft={type:r.type,org:r.org,title:r.title,cycle:r.cycle,date:'',stage:stages(r.type)[0],notes:''};go('import');}
    if(a==='openapp'){state.appId=b.dataset.id;go('detail');}
    if(a==='reportsubmitted'){const current=app();current.stage=stages(current.type)[0];current.evidence='User reported (sample)';current.history.push('User reported successful submission · No receipt created');renderDetail();say('Recorded as user reported, not receipt confirmed.');}
    if(a==='updatestage'){const current=app();if(current.evidence==='Uncertain'){say('Resolve the submission outcome before changing employer progress.');return;}current.stage=root.querySelector('#lp-stage').value;current.history.push('User-reported stage: '+current.stage+' · Preview session');renderDetail();say('Sample progress updated.');}
    if(a==='addnote'){const note=root.querySelector('#lp-note').value.trim();if(!note){say('Enter a note first.');return;}app().history.push('Note: '+note);renderDetail();say('Note added.');}
    if(a==='renewal'){if(!app().renewalTask){app().renewalTask=true;app().history.push('Renewal reminder task created · Deadline and conditions unverified');}renderDetail();say('Reminder is in the Action center. No renewal was submitted.');}
    if(a?.startsWith('mode')){captureImport();importMode=a==='modetext'?'text':a==='modefile'?'file':'details';renderImport();}
    if(a==='saveimport'){
      if(!importPreview)return;const d=state.importDraft;if(duplicate(d)){say('A matching record exists. Open it instead of saving a duplicate.');return;}
      const record={...d,id:'manual-'+Date.now(),origin:'Manual sample',evidence:'User reported (sample)',history:['Manually logged · Preview session',...(d.notes?['Note: '+d.notes]:[])]};
      state.apps.push(record);state.appId=record.id;state.importDraft=structuredClone(defaults.importDraft);state.scope='all';state.page='detail';importPreview=false;say('Sample application saved. No external submission occurred.');render();
    }
    if(a==='reset'){state=structuredClone(defaults);importMode='details';render();say('Sample data reset.');}
    persist();
  });
  root.addEventListener('submit',e=>{
    if(e.target.id!=='lp-import-form')return;e.preventDefault();captureImport();const d=state.importDraft;
    if(!d.org.trim()||!d.title.trim()||!d.cycle.trim()){say('Organization, application name, and cycle are required.');return;}
    const match=duplicate(d);importPreview=true;
    root.querySelector('#lp-import-preview').innerHTML=`<div class="callout"><h3>${match?'Possible duplicate found':'Review your record'}</h3><p>${esc(d.org)} · ${esc(d.title)} · ${esc(d.cycle)}</p><p>${esc(d.stage)} · ${d.date?esc(d.date):'Date unknown'} · User reported</p>${match?btn('Open existing application','openapp',`data-id="${esc(match.id)}"`):btn('Save sample application','saveimport','class="primary"')}</div>`;persist();
  });
  root.addEventListener('input',e=>{
    if(e.target.id==='lp-search'){state.query=e.target.value;root.querySelector('#lp-results').innerHTML=cards();}
    if(e.target.id==='lp-writing'){state.drafts[role().id]=e.target.value;if(state.approvedEssays[role().id]){state.approvedEssays[role().id]=false;const b=root.querySelector('[data-action="approvewriting"]');b.textContent='Approve sample text';b.setAttribute('aria-pressed','false');}}
    if(e.target.closest('#lp-import-form')){captureImport();importPreview=false;root.querySelector('#lp-import-preview').innerHTML='';}
  });
  root.addEventListener('change',e=>{
    if(e.target.id==='lp-track'){state.track=e.target.value;root.querySelector('#lp-results').innerHTML=cards();persist();}
    if(e.target.id==='lp-import-type'){captureImport();state.importDraft.stage=stages(state.importDraft.type)[0];importPreview=false;renderImport();persist();}
    if(e.target.id==='lp-file')root.querySelector('#lp-file-status').textContent=e.target.files[0]?'Selected: '+e.target.files[0].name+' · Not uploaded or parsed.':'No file selected.';
  });
  window.addEventListener('openai:set_globals',e=>{const s=e.detail?.globals?.widgetState?.privateContent;if(s?.version===2&&Array.isArray(s.state?.apps)){state={...structuredClone(defaults),...s.state};render();}});
  render();
  const design={spacing:26};if(globalThis.Tweak){const tweak=new Tweak({container:root,onChange:()=>{main.style.padding=design.spacing+'px';}});tweak.addSlider(design,'spacing',{label:'Content spacing',min:16,max:32,unit:'px'});}
})();
